import {
  createContext,
  useContext,
  useReducer,
  useMemo,
  useCallback,
  type ReactNode,
} from "react";
import {
  calendarReducer,
  createInitialState,
  toDateString,
  getVisibleRange,
  filterEventsInRange,
  sortEvents,
  expandRecurringEvents,
  getTimeOfDay,
  getBrowserTimeZone,
  type CalendarEvent,
  type CalendarView,
  type CalendarState,
  type CalendarAction,
  type CalendarConfig,
  type DateString,
  type DateTimeString,
  type CalendarLabels,
  type Resource,
  type EventDropExtra,
  type CustomButton,
  DEFAULT_LOCALE,
  DEFAULT_LABELS,
  DEFAULT_DAY_START_HOUR,
  DEFAULT_DAY_END_HOUR,
  DEFAULT_SNAP_DURATION,
} from "trud-calendar-core";

export type EventDropHandler = (event: CalendarEvent, newStart: DateTimeString, newEnd: DateTimeString, extra?: EventDropExtra) => void;
export type EventResizeHandler = (event: CalendarEvent, newStart: DateTimeString, newEnd: DateTimeString) => void;
export type SlotSelectHandler = (start: DateTimeString, end: DateTimeString, extra?: { resourceId?: string }) => void;

interface CalendarContextValue {
  state: CalendarState;
  dispatch: React.Dispatch<CalendarAction>;
  events: CalendarEvent[];
  visibleEvents: CalendarEvent[];
  visibleRange: { start: DateString; end: DateString };
  locale: string;
  weekStartsOn: number;
  dayStartHour: number;
  dayEndHour: number;
  snapDuration: number;
  onEventClick?: (event: CalendarEvent) => void;
  onSlotClick?: (date: DateTimeString, extra?: { resourceId?: string }) => void;
  onDateChange?: (date: DateString) => void;
  onViewChange?: (view: CalendarView) => void;
  onEventDrop?: EventDropHandler;
  onEventResize?: EventResizeHandler;
  onSlotSelect?: SlotSelectHandler;
  enableDnD?: boolean;
  enableVirtualization?: boolean;
  hiddenDays: number[];
  validRange?: { start?: DateString; end?: DateString };
  highlightedDates: Set<string>;
  showWeekNumbers: boolean;
  longPressDelay: number;
  slotClickTime: string;
  resources: Resource[];
  customButtons: CustomButton[];
  flexibleSlotTimeLimits: boolean;
  /** Resolved IANA zone in which the calendar renders times — never undefined */
  displayTimeZone: string;
  dragConstraint?: (event: CalendarEvent, newStart: DateTimeString, newEnd: DateTimeString) => boolean;
  resizeConstraint?: (event: CalendarEvent, newStart: DateTimeString, newEnd: DateTimeString) => boolean;
  selectConstraint?: (start: DateTimeString, end: DateTimeString) => boolean;
  labels: CalendarLabels;
}

const CalendarContext = createContext<CalendarContextValue | null>(null);

export function useCalendarContext(): CalendarContextValue {
  const ctx = useContext(CalendarContext);
  if (!ctx) {
    throw new Error("useCalendarContext must be used within a CalendarProvider");
  }
  return ctx;
}

interface CalendarProviderProps {
  config: CalendarConfig;
  children: ReactNode;
}

export function CalendarProvider({ config, children }: CalendarProviderProps) {
  const locale = config.locale?.locale ?? DEFAULT_LOCALE.locale;
  const weekStartsOn = config.locale?.weekStartsOn ?? DEFAULT_LOCALE.weekStartsOn;
  const dayStartHour = config.dayStartHour ?? DEFAULT_DAY_START_HOUR;
  const dayEndHour = config.dayEndHour ?? DEFAULT_DAY_END_HOUR;
  const snapDuration = config.snapDuration ?? DEFAULT_SNAP_DURATION;
  const hiddenDays = config.hiddenDays ?? [];
  const highlightedDates = useMemo(
    () => new Set(config.highlightedDates ?? []),
    [config.highlightedDates],
  );
  const showWeekNumbers = config.showWeekNumbers ?? false;
  const longPressDelay = config.longPressDelay ?? 0;
  const slotClickTime = config.slotClickTime ?? "09:00:00";
  const resources = config.resources ?? [];
  const customButtons = config.customButtons ?? [];
  const flexibleSlotTimeLimits = config.flexibleSlotTimeLimits ?? false;
  const displayTimeZone = useMemo(
    () => config.displayTimeZone ?? getBrowserTimeZone(),
    [config.displayTimeZone],
  );
  const labels: CalendarLabels = useMemo(
    () => ({ ...DEFAULT_LABELS, ...config.locale?.labels }),
    [config.locale?.labels],
  );

  // Support controlled & uncontrolled date/view
  const isDateControlled = config.date !== undefined;
  const isViewControlled = config.view !== undefined;

  const [internalState, dispatch] = useReducer(
    calendarReducer,
    createInitialState(
      config.date ?? config.defaultDate ?? toDateString(new Date()),
      config.view ?? config.defaultView ?? "month",
    ),
  );

  const state: CalendarState = {
    currentDate: isDateControlled ? config.date! : internalState.currentDate,
    view: isViewControlled ? config.view! : internalState.view,
  };

  const wrappedDispatch = useCallback(
    (action: CalendarAction) => {
      dispatch(action);

      // Fire callbacks for controlled mode
      if (action.type === "SET_VIEW" || action.type === "SET_DATE") {
        if (action.type === "SET_VIEW") config.onViewChange?.(action.payload);
        if (action.type === "SET_DATE") config.onDateChange?.(action.payload);
      }
      if (
        action.type === "NAVIGATE_PREV" ||
        action.type === "NAVIGATE_NEXT" ||
        action.type === "NAVIGATE_TODAY"
      ) {
        // We need to compute the new date to fire the callback
        const newState = calendarReducer(state, action);
        config.onDateChange?.(newState.currentDate);
      }
    },
    [state, config.onDateChange, config.onViewChange],
  );

  const visibleRange = useMemo(
    () => getVisibleRange(state.currentDate, state.view, weekStartsOn),
    [state.currentDate, state.view, weekStartsOn],
  );

  const visibleEvents = useMemo(
    () => {
      const expanded = expandRecurringEvents(config.events, visibleRange.start, visibleRange.end);
      return sortEvents(
        filterEventsInRange(expanded, visibleRange.start, visibleRange.end),
      );
    },
    [config.events, visibleRange.start, visibleRange.end],
  );

  // Compute effective time limits when flexibleSlotTimeLimits is enabled
  const effectiveDayStartHour = useMemo(() => {
    if (!flexibleSlotTimeLimits) return dayStartHour;
    let min = dayStartHour;
    for (const ev of visibleEvents) {
      if (ev.allDay || ev.display === "background") continue;
      const h = Math.floor(getTimeOfDay(ev.start));
      if (h < min) min = h;
    }
    return min;
  }, [flexibleSlotTimeLimits, dayStartHour, visibleEvents]);

  const effectiveDayEndHour = useMemo(() => {
    if (!flexibleSlotTimeLimits) return dayEndHour;
    let max = dayEndHour;
    for (const ev of visibleEvents) {
      if (ev.allDay || ev.display === "background") continue;
      const h = Math.ceil(getTimeOfDay(ev.end));
      if (h > max) max = Math.min(24, h);
    }
    return max;
  }, [flexibleSlotTimeLimits, dayEndHour, visibleEvents]);

  const value = useMemo<CalendarContextValue>(
    () => ({
      state,
      dispatch: wrappedDispatch,
      events: config.events,
      visibleEvents,
      visibleRange,
      locale,
      weekStartsOn,
      dayStartHour: effectiveDayStartHour,
      dayEndHour: effectiveDayEndHour,
      snapDuration,
      onEventClick: config.onEventClick,
      onSlotClick: config.onSlotClick,
      onDateChange: config.onDateChange,
      onViewChange: config.onViewChange,
      onEventDrop: config.onEventDrop,
      onEventResize: config.onEventResize,
      onSlotSelect: config.onSlotSelect,
      enableDnD: config.enableDnD,
      enableVirtualization: config.enableVirtualization,
      hiddenDays,
      validRange: config.validRange,
      highlightedDates,
      showWeekNumbers,
      longPressDelay,
      slotClickTime,
      resources,
      customButtons,
      flexibleSlotTimeLimits,
      displayTimeZone,
      dragConstraint: config.dragConstraint,
      resizeConstraint: config.resizeConstraint,
      selectConstraint: config.selectConstraint,
      labels,
    }),
    [
      state,
      wrappedDispatch,
      config.events,
      visibleEvents,
      visibleRange,
      locale,
      weekStartsOn,
      effectiveDayStartHour,
      effectiveDayEndHour,
      snapDuration,
      config.onEventClick,
      config.onSlotClick,
      config.onDateChange,
      config.onViewChange,
      config.onEventDrop,
      config.onEventResize,
      config.onSlotSelect,
      config.enableDnD,
      config.enableVirtualization,
      hiddenDays,
      config.validRange,
      highlightedDates,
      showWeekNumbers,
      longPressDelay,
      slotClickTime,
      resources,
      customButtons,
      flexibleSlotTimeLimits,
      displayTimeZone,
      config.dragConstraint,
      config.resizeConstraint,
      config.selectConstraint,
      labels,
    ],
  );

  return (
    <CalendarContext.Provider value={value}>
      {children}
    </CalendarContext.Provider>
  );
}
